import { quotation_billing_entities } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    deleteEntityDialog: Boolean,
    ViewEntityInfo: Object
  },
  data() {
    return {
      loading: false
    };
  },
  watch: {
    deleteEntityDialog: {
      async handler() {},
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_Entity() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(quotation_billing_entities, {
          input: {
            action_type: "DELETE",
            entity_id: this.ViewEntityInfo.entity_id
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.quotation_billing_entities);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
